import {anchorProducts,normalizeAnchor,chooseAnchorProduct,anchorMissing} from './anchors.mjs';
import {initialState,preset,catalog,materials,section,analyze} from './engine.mjs';
let s=initialState(),tab='geometry',view='model',result=null,error='',modal=false,selected='L65',saved=false,renderTimer=null;
const $=q=>document.querySelector(q),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=(n,d=2)=>Number.isFinite(n)?n.toLocaleString('ja-JP',{minimumFractionDigits:d,maximumFractionDigits:d}):'—';
const val=path=>path.split('.').reduce((o,k)=>o?.[k],s);
const options=(items,value)=>items.map(([v,t])=>`<option value="${esc(v)}" ${String(value)===String(v)?'selected':''}>${esc(t)}</option>`).join('');
const field=(label,path,unit='',min='',step='any')=>`<label class="field"><span>${label}</span><div class="unitbox"><input type="number" data-path="${path}" value="${esc(val(path))}" ${min!==''?`min="${min}"`:''} step="${step}" aria-label="${label}">${unit?`<small>${unit}</small>`:''}</div></label>`;
const textField=(label,path,placeholder='')=>`<label class="field"><span>${label}</span><input data-path="${path}" value="${esc(val(path))}" placeholder="${placeholder}" aria-label="${label}"></label>`;
const select=(label,path,items)=>`<label class="field"><span>${label}</span><select data-path="${path}" aria-label="${label}">${options(items,val(path))}</select></label>`;
const sectionOpts=Object.entries(catalog).map(([k,v])=>[k,v.label]),matOpts=Object.entries(materials).map(([k,v])=>[k,v.label]),mountOpts=[['floor','床'],['wall','壁'],['ceiling','天井']];
const checkbox=(path,label)=>`<label class="selectline"><input type="checkbox" data-path="${path}" ${val(path)?'checked':''}>${label}</label>`;
const panel=(title,content,small='',cls='')=>`<section class="panel ${cls}"><div class="panel-title">${title}<small>${small}</small></div>${content}</section>`;
const shapeIcon=t=>`<svg viewBox="0 0 70 40" fill="none" stroke="currentColor" stroke-width="2.3" stroke-linecap="round">${t==='portal'?'<path d="M12 34V8H58V34"/><path opacity=".35" d="M6 35h12m34 0h12"/>':`<path d="M15 34V8H58"/>${t==='brace'?'<path d="M15 32L58 8"/>':''}<path opacity=".35" d="M10 4v32"/>`}</svg>`;
function notify(t){$('#toast').textContent=t;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),3000);}
function run(){try{result=analyze(s);error='';}catch(e){result=null;error=e.message;}}
function header(){return `<header class="topbar"><div class="brand"><span class="mark">⌁</span><div>SUPPORT STUDIO<small>PIPE SUPPORT ENGINEERING</small></div></div><div class="topright"><span class="private">◈ ブラウザ内で計算</span><span class="tag">BETA / 一次検討</span><span class="avatar">S</span></div></header>`;}
function nav(){return `<aside class="sidebar"><div class="workspace">DESIGN WORKSPACE</div>${[['geometry','⌑','形状・寸法'],['material','▱','鋼材・曲げ加工'],['loads','↓','荷重条件'],['anchor','⊥','アンカー'],['report','▤','計算書']].map(([id,ic,label])=>`<button class="navbtn ${tab===id?'active':''}" data-tab="${id}"><span>${ic}</span>${label}</button>`).join('')}<div class="sidefoot"><strong><span class="dot"></span>平面フレーム解析</strong>寸法 mm ／ 荷重 kN<br>線形弾性・面内の一次検討<br><br><button class="small-btn" data-action="method" style="background:transparent;color:#bbd2c5;border-color:#42625b">計算方法・適用範囲 ↗</button><p>SUPPORT STUDIO<br>VERSION 1.1</p></div></aside>`;}
function render(){clearTimeout(renderTimer);run();document.title=`${s.name} | SUPPORT STUDIO`;
 $('#app').innerHTML=header()+`<div class="layout">${nav()}<main class="main"><div class="breadcrumb">ワークスペース <span>／ 配管架台の構造検討</span></div><div class="pagehead"><div><h1>${esc(s.name)}</h1><p>形状から固定部まで、架台の条件をひとつのモデルで検討。</p></div><div class="actions"><button data-action="load">読込</button><button data-action="save">↓ データ保存</button><button class="primary" data-action="export-report">▤ 計算書を出力</button></div></div><div class="report-head"><h1>${esc(s.name)}</h1>配管架台 構造一次検討書 ／ ${new Date().toLocaleDateString('ja-JP')}<br>平面線形弾性解析・設計承認用の最終計算書ではありません。</div><div class="subbar"><div class="tabs">${[['geometry','形状・寸法'],['material','鋼材・曲げ加工'],['loads','荷重'],['anchor','アンカー'],['report','計算結果']].map(([id,t])=>`<button class="${tab===id?'active':''}" data-tab="${id}">${t}</button>`).join('')}</div><div class="revision">${saved?'ローカル保存済み':'入力と同時に再計算'} <span class="dot" style="margin-left:7px"></span></div></div>${error?`<div class="note danger engine-error" role="alert">計算できません：${esc(error)}</div>`:''}${tab==='geometry'?geometry():tab==='material'?material():tab==='loads'?loads():tab==='anchor'?anchor():report()}<div class="footer-note"><span>ⓘ 面内の一次検討です。接合部・面外安定・基礎・局部座屈の最終確認が別途必要です。</span><button class="small-btn" data-action="method">計算根拠・適用範囲 ↗</button></div></main></div>${modal?`<div class="modal-back"><div class="modal" role="dialog" aria-modal="true" aria-label="計算方法と適用範囲"><div class="panel-title">計算方法と適用範囲<button data-action="close">閉じる ×</button></div><div class="large-body">${method()}</div></div></div>`:''}`;
}
function geometry(){return `<div class="workgrid">${panel('架台の設定',`<div class="body"><div class="section-label"><span class="step-num">01</span>基本形状</div><div class="shape-picks">${[['l','L型'],['brace','ブレース付き'],['portal','門型']].map(([k,t])=>`<button class="shape-pick ${s.type===k?'active':''}" data-preset="${k}">${shapeIcon(k)}${t}</button>`).join('')}</div><div class="section-label"><span class="step-num">02</span>取付面</div><div class="segmented">${mountOpts.map(([k,t])=>`<button data-mount="${k}" class="${s.mount===k?'active':''}">${t}</button>`).join('')}</div><div class="twocol">${field('幅 / 張出し W','w','mm',1)}${field('高さ H','h','mm',1)}</div><button data-action="regenerate" class="small-btn" style="width:100%">この寸法で形状を更新 ↗</button><p class="help">更新時は節点・部材・荷重をテンプレートに戻します。自由編集は下の表で行えます。</p><div class="sep"></div><div class="section-label"><span class="step-num">03</span>鋼材</div>${select('材質','material',matOpts)}${select('部材断面','defaultSection',sectionOpts)}<button data-action="apply-all" class="small-btn" style="width:100%">全ての部材に材質・断面を適用</button><div class="sep"></div>${textField('案件名','name')}<div class="note">全節点は剛接合モデル。ブレースも曲げ剛性を持つ部材として計算します。</div></div>`,'PARAMETERS')}<div>${preview()}${summary()}${checks()}</div></div>${editor()}`;}
function preview(){return panel('構造モデル',`<div class="preview"><div class="preview-toolbar"><div class="mini-tabs"><button data-view="model" class="${view==='model'?'active':''}">形状</button><button data-view="deform" class="${view==='deform'?'active':''}">変形</button></div><span class="tag">2D · 正面図</span></div>${modelSvg()}<div class="legend"><span><i style="background:#678b7e"></i>鋼材</span><span><i style="background:#d87e5b"></i>外力</span><span>○ 節点</span><span style="margin-left:auto">mm</span></div></div>`,`${s.nodes.length} NODES / ${s.members.length} MEMBERS`);}
function modelSvg(){const ns=s.nodes;if(!ns.length)return '<div class="empty">節点を追加してください。</div>';const xs=ns.map(n=>n.x),ys=ns.map(n=>n.y);const minx=Math.min(...xs),maxx=Math.max(...xs),miny=Math.min(...ys),maxy=Math.max(...ys),scale=Math.min(410/Math.max(maxx-minx,1),220/Math.max(maxy-miny,1));const ox=315-(minx+maxx)/2*scale,oy=205+(miny+maxy)/2*scale;const p=(n,dx=0,dy=0)=>[ox+(n.x+dx)*scale,oy-(n.y+dy)*scale];let content='';
 for(const n of ns){if(n.fix==='free')continue;const [x,y]=p(n);const rotate=n.mount==='wall'?90:n.mount==='ceiling'?180:0;content+=`<g transform="translate(${x} ${y}) rotate(${rotate})"><path d="M-22 6h44v12h-44z" fill="url(#hatch)" stroke="#c3cfc0"/><path d="M-25 5H25" stroke="#94a78d" stroke-width="2"/>${n.fix==='pin'?'<path d="M0 0l-8 5h16z" fill="#73896f"/>':'<rect x="-8" y="-5" width="16" height="10" rx="1" fill="#9aa995"/>'}<circle cx="-15" cy="4" r="2.2" fill="#6d7f65"/><circle cx="15" cy="4" r="2.2" fill="#6d7f65"/></g>`;}
 const factor=result&&result.maxDisp>0?Math.min(5000,25/(result.maxDisp*scale)):1;
 for(const m of s.members){const a=ns.find(n=>n.id===m.a),b=ns.find(n=>n.id===m.b);if(!a||!b)continue;const [x1,y1]=p(a),[x2,y2]=p(b);content+=`<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" stroke="#637f70" stroke-width="9"/><line x1="${x1-1}" y1="${y1-1}" x2="${x2-1}" y2="${y2-1}" stroke="#9fb4a2" stroke-width="3"/><rect x="${(x1+x2)/2-12}" y="${(y1+y2)/2-26}" width="25" height="17" rx="4" fill="#f8fbf4" stroke="#d8e4d1"/><text x="${(x1+x2)/2}" y="${(y1+y2)/2-14}" text-anchor="middle" fill="#7d9376" font-size="9">M${m.id}</text>`;
 if(view==='deform'&&result){const rr=result.results.find(r=>r.id===m.id),L=rr.L,dx=b.x-a.x,dy=b.y-a.y,c=dx/L,d=dy/L;const path=[];for(let j=0;j<=30;j++){const t=j/30,u=rr.ul,xx=t*L;const q=s.selfWeight?-rr.p.A*1e-9*materials[m.material].rho*9.80665*s.factor:0;const ux=u[0]*(1-t)+u[3]*t+q*d*xx*(L-xx)/(2*materials[m.material].E*rr.p.A);const uy=(1-3*t*t+2*t**3)*u[1]+L*(t-2*t*t+t**3)*u[2]+(3*t*t-2*t**3)*u[4]+L*(-t*t+t**3)*u[5]+q*c*xx*xx*(L-xx)**2/(24*materials[m.material].E*rr.p.I);const pp=p({x:a.x+dx*t,y:a.y+dy*t},factor*(c*ux-d*uy),factor*(d*ux+c*uy));path.push(`${j?'L':'M'}${pp[0]} ${pp[1]}`);}content+=`<path d="${path.join(' ')}" stroke="#dc8465" stroke-width="2" fill="none" stroke-dasharray="6 4"/>`;}}
 for(const n of ns){const [x,y]=p(n);content+=`<circle cx="${x}" cy="${y}" r="4.2" fill="#f9fcf5" stroke="#557568" stroke-width="2"/><text x="${x+12}" y="${y+17}" fill="#81947a" font-size="10">${n.id}</text>`;}
 for(const l of s.loads){const n=ns.find(n=>n.id===l.node);if(!n)continue;const [x,y]=p(n);if(l.fy){const sign=l.fy>0?1:-1,top=y+sign*64,end=y+sign*13;content+=`<line x1="${x}" y1="${top}" x2="${x}" y2="${end}" stroke="#da7f5c" stroke-width="2" marker-end="url(#arrow)"/><text x="${x+9}" y="${top+4}" fill="#c87a57" font-size="11">${fmt(Math.abs(l.fy*s.factor),2)} kN</text>`;}if(l.fx){const sign=l.fx>0?1:-1;content+=`<line x1="${x-sign*60}" y1="${y-10}" x2="${x-sign*13}" y2="${y-10}" stroke="#da7f5c" stroke-width="2" marker-end="url(#arrow)"/><text x="${x-sign*60}" y="${y-23}" fill="#c87a57" font-size="10">Fx ${fmt(l.fx*s.factor)} kN</text>`;}if(l.mz)content+=`<text x="${x+15}" y="${y+33}" fill="#c87a57" font-size="10">↶ ${fmt(l.mz*s.factor)} kN·m</text>`;}
 const left=ox+minx*scale,right=ox+maxx*scale,bottom=oy-miny*scale,top=oy-maxy*scale;content+=`<path d="M${left} ${bottom+25}v18m0 -5H${right}m0 -13v18" stroke="#acbaa4" fill="none"/><text x="${(left+right)/2}" y="${bottom+54}" font-size="11" fill="#86987b" text-anchor="middle">${fmt(maxx-minx,0)}</text><path d="M${left-34} ${top}h-18m5 0V${bottom}m-5 0h18" stroke="#acbaa4" fill="none"/><text x="${left-54}" y="${(top+bottom)/2}" font-size="11" fill="#86987b" text-anchor="middle" transform="rotate(-90 ${left-54} ${(top+bottom)/2})">${fmt(maxy-miny,0)}</text>`;
 return `<svg class="model" viewBox="0 0 630 400" role="img" aria-label="架台の構造モデルと荷重"><defs><pattern id="hatch" width="7" height="7" patternUnits="userSpaceOnUse"><path d="M-1 7L7 -1M5 9L9 5" stroke="#c8d2bf" stroke-width="1"/></pattern><marker id="arrow" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="5" markerHeight="5" orient="auto-start-reverse"><path d="M0 0L10 5L0 10z" fill="#da7f5c"/></marker></defs>${content}<path d="M32 355v-29m0 29h29" stroke="#a0b295" stroke-width="1.3"/><text x="22" y="321" fill="#92a58a" font-size="9">Y</text><text x="65" y="359" fill="#92a58a" font-size="9">X</text><text x="600" y="378" text-anchor="end" font-size="9" fill="#8a9e7e">${view==='deform'&&result?'変形倍率 ×'+fmt(factor,0):'寸法に連動 / 正面投影'}</text></svg>`;
}
function summary(){return `<div class="summary">${[['最大応力度',result?.maxStress,'N/mm²',2],['最大変位',result?.maxDisp,'mm',3],['鋼材質量',result?.weight,'kg',2]].map(([label,v,unit,d])=>`<div class="metric"><div class="metric-label">${label}</div><div class="metric-number">${fmt(v,d)}<small>${unit}</small></div><div class="metric-sub">${label==='最大応力度'?'軸力＋曲げの上限値':label==='最大変位'?'節点・部材内の合成変位':'形鋼・曲げ板のみ'}</div></div>`).join('')}</div>`;}
function checkRow(label,ratio){return `<div class="result-line"><span>${label}</span><div class="track ${ratio>1?'red':''}"><i style="width:${ratio===null||ratio===undefined?0:Math.min(100,ratio*100)}%"></i></div><span style="text-align:right">${ratio===null||ratio===undefined?'—':fmt(ratio,2)}</span><span class="badge ${ratio===null||ratio===undefined?'pending':ratio>1?'red':''}">${ratio===null||ratio===undefined?'条件未設定':ratio>1?'超過':'範囲内'}</span></div>`;}
function checks(){return panel('一次照査',`${checkRow('部材応力度',result?.memberRatio)}${checkRow('変位',result?.defRatio)}${checkRow('アンカー',result?.anchorRatio)}<div class="body" style="padding-top:12px;padding-bottom:12px"><span class="help">比率 ＝ 計算値 / 入力限度値。総合的な構造安全性の判定は行いません。</span></div>`,'DEMAND / LIMIT','results');}
function editor(){return `<div class="full">${panel('自由形状エディタ',`<div class="body"><div class="note">節点座標と接続先を入力して形状を変更できます。Yは上向き正。交差する部材を接合する場合は、交点に節点を追加して部材を分割してください。</div></div><div class="table-wrap"><table><thead><tr><th>節点</th><th>X (mm)</th><th>Y (mm)</th><th>支点条件</th><th>取付面</th><th></th></tr></thead><tbody>${s.nodes.map((n,i)=>`<tr><td>N${n.id}</td><td><input type="number" data-path="nodes.${i}.x" value="${n.x}" aria-label="節点${n.id} X"></td><td><input type="number" data-path="nodes.${i}.y" value="${n.y}" aria-label="節点${n.id} Y"></td><td><select data-path="nodes.${i}.fix" aria-label="節点${n.id} 支点">${options([['free','自由'],['fixed','固定'],['pin','ピン']],n.fix)}</select></td><td><select data-path="nodes.${i}.mount" aria-label="節点${n.id} 取付面">${options(mountOpts,n.mount)}</select></td><td><button class="delete" data-delete="nodes.${i}" aria-label="節点${n.id}を削除">×</button></td></tr>`).join('')}</tbody></table></div><div class="table-actions"><button class="small-btn" data-action="add-node">＋ 節点</button><span class="counter">${s.nodes.length} / 40</span></div><div class="table-wrap"><table><thead><tr><th>部材</th><th>始点</th><th>終点</th><th>断面</th><th>材質</th><th>有効長係数 K</th><th></th></tr></thead><tbody>${s.members.map((m,i)=>`<tr><td>M${m.id}</td>${['a','b'].map(k=>`<td><select data-path="members.${i}.${k}" data-number="true" aria-label="部材${m.id} ${k==='a'?'始点':'終点'}">${options(s.nodes.map(n=>[n.id,'N'+n.id]),m[k])}</select></td>`).join('')}<td><select class="wide" data-path="members.${i}.section" aria-label="部材${m.id} 断面">${options(sectionOpts,m.section)}</select></td><td><select data-path="members.${i}.material" aria-label="部材${m.id} 材質">${options(matOpts,m.material)}</select></td><td><input type="number" value="${m.k}" min="0.1" step="0.1" data-path="members.${i}.k" aria-label="部材${m.id} 有効長係数"></td><td><button class="delete" data-delete="members.${i}" aria-label="部材${m.id}を削除">×</button></td></tr>`).join('')}</tbody></table></div><div class="table-actions"><button class="small-btn" data-action="add-member">＋ 部材</button><span class="counter">${s.members.length} / 80</span></div>`,'COORDINATES & CONNECTIONS')}</div>`;}
function sectionDrawing(p){if(p.kind==='BENT'&&p.points){const xs=p.points.map(v=>v[0]),ys=p.points.map(v=>v[1]),mi=Math.min(...xs),ma=Math.max(...xs),lo=Math.min(...ys),hi=Math.max(...ys),sc=Math.min(160/(ma-mi||1),110/(hi-lo||1));return `<svg class="section-svg" viewBox="0 0 280 160" role="img" aria-label="曲げ板断面"><path d="${p.points.map((q,i)=>`${i?'L':'M'}${140+(q[0]-(mi+ma)/2)*sc} ${80-(q[1]-(lo+hi)/2)*sc}`).join(' ')}" stroke="#69917a" stroke-width="${Math.max(3,s.bent.t*sc)}" fill="none" stroke-linejoin="miter"/><circle cx="${140+(p.cx-(mi+ma)/2)*sc}" cy="${80-(p.cy-(lo+hi)/2)*sc}" r="3" fill="#d57a56"/><text x="12" y="145" font-size="9" fill="#8a9d81">● 図心 / 曲げR省略</text></svg>`;}return `<svg class="section-svg" viewBox="0 0 280 160" role="img" aria-label="断面の模式図"><g transform="translate(95 30)" fill="#96b19a" stroke="#587f64" stroke-width="1.5">${p.kind==='L'?'<path d="M0 0h12v88h78v12H0z"/>':p.kind==='H'?'<path d="M0 0h90v12H51v76h39v12H0V88h39V12H0z"/>':p.kind==='C'?'<path d="M0 0h90v12H12v76h78v12H0z"/>':p.kind==='RECT'?'<path fill-rule="evenodd" d="M0 0h90v100H0zM9 9v82h72V9z"/>':'<path d="M0 0h90v100H0z"/>'}</g><text x="12" y="147" font-size="9" fill="#899e82">模式図・断面高さ方向に曲げ</text></svg>`;}
function material(){let p=null,pe='';try{p=section(s,selected);}catch(e){pe=e.message;}
 return `<div class="detailgrid"><div>${panel('断面ライブラリ',`<div class="large-body"><label class="field"><span>編集する断面</span><select id="section-edit">${options(sectionOpts,selected)}</select></label>${['RECT','H','C'].includes(selected)?`<div class="twocol">${field('高さ H','dims.h','mm',1)}${field('幅 B','dims.b','mm',1)}${field('板厚 / ウェブ t','dims.t','mm',.1)}${selected!=='RECT'?field('フランジ tf','dims.tf','mm',.1):''}</div><div class="note">任意寸法の矩形合成断面です。JIS形鋼の隅R・フランジ勾配を省略します。厳密な断面性能は「直接入力」で指定してください。</div>`:selected==='BENT'?`<div class="threecol">${field('板厚 t','bent.t','mm',.1)}${field('内R','bent.r','mm',0)}${field('K値','bent.k','',0,.01)}</div><div class="help">各辺は曲げ接線間の直線長。曲げ角は次の辺への回転角（反時計回り＋）。最終辺の曲げ角は使いません。</div><div class="table-wrap"><table><thead><tr><th>辺</th><th>直線長 mm</th><th>曲げ角 °</th><th></th></tr></thead><tbody>${s.bent.legs.map((l,i)=>`<tr><td>${i+1}</td><td><input type="number" data-path="bent.legs.${i}.length" value="${l.length}" min="1" aria-label="辺${i+1}直線長"></td><td>${i===s.bent.legs.length-1?'—':`<input type="number" data-path="bent.legs.${i}.turn" value="${l.turn}" min="-174" max="174" aria-label="辺${i+1}曲げ角">`}</td><td><button class="delete" data-delete="bent.legs.${i}" aria-label="辺${i+1}削除">×</button></td></tr>`).join('')}</tbody></table></div><div class="table-actions"><button class="small-btn" data-action="add-leg">＋ 曲げ辺</button><button class="small-btn" data-bent="l">L断面</button><button class="small-btn" data-bent="u">コの字</button><button class="small-btn" data-bent="z">Z断面</button></div><div class="note warning">断面は直線要素近似です。曲げR部、断面の重なり、局部座屈・加工硬化は計算対象外。自己交差する断面には使用できません。</div>`:selected==='MANUAL'?`<div class="twocol">${field('断面積 A','manual.A','mm²',1)}${field('面内 I','manual.I','mm⁴',1)}${field('最小主軸 Imin','manual.Imin','mm⁴',1)}${field('断面係数 Z','manual.Z','mm³',1)}${field('せん断参照面積 Av','manual.Av','mm²',1)}</div>${textField('断面性能の出典','manualSource','メーカー名・資料名・版')}`:`<div class="note">JIS G 3192 等辺山形鋼の代表寸法。断面性能はJFE鋼材資料の掲載値です。SUS304は製品寸法・成形方法が一致する場合の幾何形状として使用します。</div>`}<div class="sep"></div><button class="primary" data-action="apply-section">この断面を全ての部材に適用</button><p class="help">部材ごとの断面・材質は「形状・寸法」の表で変更できます。寸法入力断面と曲げ断面は、種類ごとに共通の寸法を使用します。</p></div>`)}${panel('材質と照査限度',`<div class="body"><div class="note warning">許容応力度は設計基準・板厚・温度・荷重条件を確認して入力してください。0 の項目は未設定として扱います。</div>${matOpts.map(([m,t])=>`<div class="section-label" style="margin-top:18px">${t} <span class="counter">E = ${fmt(materials[m].E,0)} N/mm²</span></div><div class="twocol">${field('軸力＋曲げの限度','allow.'+m+'.normal','MPa',0)}${field('せん断の限度','allow.'+m+'.shear','MPa',0)}</div>`).join('')}<p class="material-hint">SSはSS400を実装。SUS304と建築構造用SUS304Aは同一の設計強度として扱えません。</p>${field('合成変位の限度','deflection','mm',.01)}</div>`,'USER DEFINED','full')}</div><div>${panel('断面プレビュー',`<div class="large-body">${p?sectionDrawing(p):`<div class="note danger">${esc(pe)}</div>`}${p?`<div class="stat-grid" style="margin-top:16px">${[['断面積 A',p.A,'mm²'],['面内 I',p.I,'mm⁴'],['断面係数 Z',p.Z,'mm³'],['最小主軸 Imin',p.Imin,'mm⁴'],['せん断参照面積 Av',p.Av,'mm²'],...(p.developed?[['展開長（概算）',p.developed,'mm']]:[])].map(([label,v,u])=>`<div class="stat"><small>${label}</small>${fmt(v,1)} <span class="muted">${u}</span></div>`).join('')}</div><p class="help">${esc(p.source)}。開断面はねじれ・面外変形を拘束した面内モデルです。</p>`:''}</div>`)}${preview()}${checks()}</div></div>`;
}
function loads(){return `<div class="detailgrid"><div>${panel('荷重ケース',`<div class="large-body"><div class="note">Fxは右向き、Fyは上向き、Mzは反時計回りが正。配管・流体・保温材等の合計荷重を支持位置の節点に入力します。</div><div class="table-wrap" style="margin-top:15px"><table><thead><tr><th>節点</th><th>Fx kN</th><th>Fy kN</th><th>Mz kN·m</th><th></th></tr></thead><tbody>${s.loads.map((l,i)=>`<tr><td><select data-path="loads.${i}.node" data-number="true" aria-label="荷重${i+1}節点">${options(s.nodes.map(n=>[n.id,'N'+n.id]),l.node)}</select></td>${['fx','fy','mz'].map(k=>`<td><input type="number" step="0.1" value="${l[k]}" data-path="loads.${i}.${k}" aria-label="荷重${i+1} ${k}"></td>`).join('')}<td><button class="delete" data-delete="loads.${i}" aria-label="荷重${i+1}削除">×</button></td></tr>`).join('')}</tbody></table></div><div class="table-actions"><button class="small-btn" data-action="add-load">＋ 荷重</button></div><div class="sep"></div>${field('荷重倍率（自重にも適用）','factor','倍',.01)}${checkbox('selfWeight','鋼材自重を含める（鉛直下向き）')}<p class="help">接合板・アンカー・溶接・配管の自重は自動集計しません。追加荷重として入力してください。地震・風・熱応力・振動の自動荷重生成や荷重組合せは未実装です。</p>${field('合成変位の限度','deflection','mm',.01)}</div>`)}${panel('設計メモ',`<div class="body"><label class="field slim"><span>荷重の根拠・検討条件</span><textarea data-path="note" rows="5" placeholder="例：満水時の配管重量、支持間隔、荷重の根拠資料…">${esc(s.note)}</textarea></label></div>`,'','full')}</div><div>${preview()}${summary()}${checks()}</div></div>`;}
function anchor(){return `<div class="detailgrid"><div>${panel('固定部の条件',`<div class="large-body">${anchorProductFields()}<div class="twocol">${field('呼び径','anchor.diameter','mm',1)}${field('1支点あたりの本数','anchor.count','本',2,2)}${field('2列間のピッチ','anchor.pitch','mm',1)}${field('有効埋込み長さ','anchor.embed','mm',1)}${field('最小へりあき','anchor.edge','mm',1)}${field('コンクリート Fc','anchor.fc','MPa',1)}${field('母材厚さ','anchor.thickness','mm',1)}</div><div class="note">同一本数を2列に等分し、全支点に共通のアンカー条件を適用します。ピッチは曲げモーメントに抵抗する2列間の距離です。</div><div class="sep"></div><div class="section-label">製品資料から入力する許容耐力</div><div class="twocol">${field('1本あたり 引張 Na','anchor.nt','kN',0)}${field('1本あたり せん断 Va','anchor.vt','kN',0)}</div><p class="material-hint">呼び径・埋込み・へりあき・Fc・母材厚さは記録項目です。耐力へ自動反映しません。群効果、ひび割れ、施工方向等を反映した値を入力してください。</p>${checkbox('anchor.confirmed','入力した耐力が実際の配置・施工条件に適用可能と確認済み')}<p class="help">${s.anchor.type==='chemical'?'接着系：天井施工の適用、持続引張・クリープ、温度、孔内清掃、硬化時間を製品資料で確認してください。':'金属拡張：母材厚さ、へりあき、打込み・締付条件、ひび割れコンクリートへの適用を製品資料で確認してください。'}</p></div>`,'全支点に共通')}</div><div>${panel('アンカーの照査',`<div class="body"><div class="note warning">これは支点反力からの簡易荷重配分です。コンクリート破壊、付着破壊、ベースプレート曲げ、こじり力は別途確認が必要です。</div></div>${anchorTable()}<div class="body"><div class="method">引張 T = max(0, N) / n + 2|M| / (n p)<br>せん断 V = |Q| / n<br>照査比 = T / Na + V / Va<br><span class="help">圧縮軸力による引張低減を見込まず、偶力間距離をpと仮定。引張とせん断の線形和による参考照査です。製品指定の相関式との適合は別途確認してください。</span></div></div>`)}${preview()}</div></div>`;}
function anchorTable(){return `<div class="table-wrap"><table><thead><tr><th>支点</th><th>取付</th><th>最大引張/本</th><th>せん断/本</th><th>比率</th><th>参考照査</th></tr></thead><tbody>${result?result.supports.map(r=>`<tr><td>N${r.id}</td><td>${mountOpts.find(x=>x[0]===r.mount)?.[1]||'—'}</td><td>${fmt(r.tension)} kN</td><td>${fmt(r.shear)} kN</td><td>${r.ratio===null?'—':fmt(r.ratio)}</td><td><span class="badge ${r.ratio===null?'pending':r.ratio>1?'red':''}">${r.ratio===null?'条件未設定':r.ratio>1?'超過':'範囲内'}</span></td></tr>`).join(''):'<tr><td colspan="6">計算結果なし</td></tr>'}</tbody></table></div>`;}
function report(){return `${panel('検討の状態',`<div class="body"><div class="note ${(result?.memberRatio>1||result?.anchorRatio>1||result?.defRatio>1||result?.euler>=1)?'danger':'warning'}">${error?'モデルの入力を修正してください。':result?.memberRatio>1||result?.anchorRatio>1||result?.defRatio>1?'入力限度を超えている項目があります。':result?.memberRatio===null||result?.anchorRatio===null?'許容値または製品条件が未設定のため、照査は未完了です。':'入力した限度内の一次検討結果です。最終設計には未評価項目の確認が必要です。'}${result?.euler>=1?' 弾性座屈荷重に達している部材があります。':''}</div></div>`)}<div class="detailgrid full"><div>${preview()}</div><div>${summary()}${checks()}</div></div>${panel('部材の解析結果',`<div class="table-wrap"><table><thead><tr><th>部材 / 材質</th><th>断面</th><th>長さ mm</th><th>|N| kN</th><th>|V| kN</th><th>|M| kN·m</th><th>σ MPa</th><th>τ参考 MPa</th><th>応力比</th><th>Nc / Ne</th></tr></thead><tbody>${result?result.results.map(r=>`<tr><td>M${r.id} / ${r.material}</td><td>${esc(r.p.label)}</td><td>${fmt(r.L,1)}</td><td>${fmt(r.N)}</td><td>${fmt(r.V)}</td><td>${fmt(r.M,3)}</td><td>${fmt(r.sigma)}</td><td>${fmt(r.tau)}</td><td>${r.ratio===null?'未設定':fmt(r.ratio)}</td><td>${fmt(r.euler,3)}</td></tr>`).join(''):'<tr><td colspan="10">計算結果なし</td></tr>'}</tbody></table></div><div class="body help">σ = max|N|/A + max|M|/Z（上限値）。τ = 1.5 max|V|/Av（参考値）。Nc/NeはEuler座屈荷重に対する比率で、設計用の座屈照査ではありません。</div>`,'部材内の最大値','full')}${panel('支点反力',`<div class="table-wrap"><table><thead><tr><th>支点</th><th>Rx kN</th><th>Ry kN</th><th>Mz kN·m</th></tr></thead><tbody>${result?result.supports.map(r=>`<tr><td>N${r.id}</td><td>${fmt(r.rx,3)}</td><td>${fmt(r.ry,3)}</td><td>${fmt(r.m,4)}</td></tr>`).join(''):''}</tbody></table></div>`,'X右＋ / Y上＋ / M反時計回り＋','full')}${panel('アンカー荷重・参考照査',anchorTable(),'','full')}${panel('計算条件・入力データ',`<div class="body print-condition">${conditions()}</div>`,'','full')}${panel('計算根拠・適用範囲',`<div class="large-body">${method()}</div>`,'','full')}`;}
function conditions(){return `<p>案件：${esc(s.name)} ／ 荷重倍率：${fmt(s.factor)} ／ 自重：${s.selfWeight?'含む':'含まない'} ／ 変位限度：${fmt(s.deflection)} mm</p><p>${matOpts.map(([k])=>`${k}：E ${materials[k].E} N/mm²、ρ ${materials[k].rho} kg/m³、応力限度 ${s.allow[k].normal||'未設定'} MPa、せん断限度 ${s.allow[k].shear||'未設定'} MPa`).join('<br>')}</p><p>節点：${s.nodes.map(n=>`N${n.id} (${n.x}, ${n.y}) ${n.fix} / ${n.mount}`).join(' ／ ')}</p><p>部材：${s.members.map(m=>`M${m.id} N${m.a}→N${m.b}、${esc(catalog[m.section]?.label)}、${m.material}、K=${m.k}`).join('<br>')}</p><p>使用断面性能：${[...new Set(s.members.map(m=>m.section))].map(key=>{try{const p=section(s,key);return `${esc(p.label)}：A=${fmt(p.A,2)} mm²、I=${fmt(p.I,1)} mm⁴、Imin=${fmt(p.Imin,1)} mm⁴、Z=${fmt(p.Z,1)} mm³、Av=${fmt(p.Av,1)} mm²（${esc(p.source)}）`;}catch{return '断面不正';}}).join('<br>')}</p><p>入力荷重（倍率適用前）：${s.loads.map(l=>`N${l.node} Fx=${l.fx} kN, Fy=${l.fy} kN, Mz=${l.mz} kN·m`).join('<br>')||'なし'}</p><p>アンカー：${s.anchor.type==='metal'?'金属拡張':'接着系'} / ${esc(s.anchor.product)||'製品未指定'} / 呼び径 ${s.anchor.diameter} mm / ${s.anchor.count}本/支点 / ピッチ ${s.anchor.pitch} mm / 埋込み ${s.anchor.embed} mm / へりあき ${s.anchor.edge} mm / Fc ${s.anchor.fc} MPa / 母材厚 ${s.anchor.thickness} mm / Na ${s.anchor.nt||'未設定'} kN / Va ${s.anchor.vt||'未設定'} kN / 条件確認 ${s.anchor.confirmed?'済':'未'}</p>${s.members.some(m=>m.section==='BENT')?`<p>曲げ板：t=${s.bent.t} mm、R=${s.bent.r} mm、K=${s.bent.k} ／ 直線長・次辺への角度 ${s.bent.legs.map(l=>`${l.length} mm / ${l.turn}°`).join('、')}</p>`:''}${anchorReportDetails()}<p>設計メモ：${esc(s.note).replace(/\n/g,'<br>')||'—'}</p>`;}
function method(){return `<div class="method"><h3>01　解析モデル</h3><p>2次元Euler–Bernoulliフレームの直接剛性法。各節点は水平変位・鉛直変位・回転の3自由度で、全接合部を剛接とします。小変形・線形弾性・常温を仮定します。自重は部材に沿う等分布荷重として等価節点荷重と固定端力に反映します。部材内変位は101点の補間値、曲げ最大値は分布荷重による極値も評価します。</p><h3>02　部材の参考照査</h3><p>軸力と曲げの応力度は |N|/A + |M|/Z の最大値の和で上限評価します。せん断は 1.5|V|/Av の簡易値です。Avは山形鋼の一辺の直線部、H・溝形はウェブ、角形は両ウェブ、曲げ板はA/2とした参照面積であり、一般断面の厳密なせん断分布は求めません。許容値は利用者の入力です。Euler荷重 Ne = π²EImin/(KL)² は参考表示のみです。</p><h3>03　断面と曲げ加工</h3><p>等辺山形鋼3種類はメーカー断面表の値。角形・H・溝形の寸法入力は矩形合成の近似断面です。曲げ板は直線中心線要素の面積・図心・二次モーメント・相乗モーメントからIminを求めます。断面係数は面内I/縁距離。断面は曲げR部分を省略し、展開長のみ各曲げの |θ| (R + Kt) を加算します。外寸法を直線長にそのまま入力しないでください。K値は実際の加工条件で補正が必要です。</p><h3>04　アンカー</h3><p>全支点に共通の2列均等配置を仮定。床・壁・天井の面法線に沿って支点反力を引張とせん断へ変換し、圧縮軸力の引張低減を見込まない荷重配分を使用します。T=max(0,N)/n+2|M|/(np)、V=|Q|/n。入力許容耐力に対する線形和で参考照査します。径・埋込み・へりあき・Fc・母材厚は記録のみで、強度を自動算定しません。</p><h3>05　未評価の項目</h3><p>面外荷重・ねじり・非対称断面の非拘束曲げ・横座屈・局部座屈・設計用の圧縮座屈・接合部・溶接・ボルト・ベースプレート・こじり・コンクリート破壊・付着・群効果・基礎・耐震荷重組合せ・熱変形・疲労・振動・塑性化・2次効果は対象外。曲げ板の自己交差や製作可能性は確認が必要です。SUS304はSUS304Aの設計基準強度を流用しません。</p><h3>06　参照資料</h3><ul><li><a href="https://www.jfe-steel.co.jp/products/building/assets/pdf/shapes/angle-danmen.pdf" target="_blank" rel="noopener">JFEスチール：山形鋼の形状寸法・断面性能</a>（L50×50×6、L65×65×6、L75×75×6）</li><li><a href="https://www.nipponsteel.com/product/construction/handbook/pdf/3-35.pdf" target="_blank" rel="noopener">日本製鉄：建築構造材に使用されるステンレス鋼と接合材</a>（SUS304のE=193 GPa、密度7.93。炭素鋼E=205 GPaを入力モデルに使用）</li><li><a href="https://www.hilti.co.jp/engineering/articles/article-anchor-design-layout-and-installation" target="_blank" rel="noopener">Hilti：アンカー設計・配置と施工</a></li><li><a href="https://www.hilti.co.jp/engineering/articles/article-anchor-design-simple-calculation-example" target="_blank" rel="noopener">Hilti：アンカー設計の計算例</a>（耐力が製品・施工条件に依存することの参考）</li></ul><p>このアプリは上記資料やJISへの包括的な適合を認証するものではありません。案件の設計基準に基づく最終確認を行ってください。</p></div>`;}
function regenerate(){if(!(s.w>0&&s.h>0))return notify('幅と高さを正の値で入力してください。');Object.assign(s,preset(s.type,s.mount,s.w,s.h,s.defaultSection,s.material));saved=false;render();}
function save(){const payload={...s,version:1};try{localStorage.setItem('support-studio-v1',JSON.stringify(payload));saved=true;}catch{}const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=(s.name||'pipe-support').replace(/[<>:"/\\|?*]/g,'_')+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),3000);render();notify('検討データをJSONファイルに保存しました。');}
function loadState(data){if(!data||data.version!==1||!Array.isArray(data.nodes)||!Array.isArray(data.members)||!Array.isArray(data.loads)||!data.bent||!data.anchor||!data.allow)throw Error('対応する検討データではありません。');const forbidden=['__proto__','prototype','constructor'];function safe(o){if(o&&typeof o==='object')for(const k of Object.keys(o)){if(forbidden.includes(k))throw Error('不正なデータです。');safe(o[k]);}}safe(data);if(data.nodes.length>40||data.members.length>80||data.loads.length>100||data.bent.legs?.length>12)throw Error('データが上限を超えています。');data.anchor=normalizeAnchor(data.anchor);analyze(data);s=data;selected=s.defaultSection||'L65';saved=true;render();}
function handleField(e){const el=e.target;if(el.id==='section-edit'){selected=el.value;render();return;}const path=el.dataset.path;if(!path)return;if(path==='anchor.catalogId'){s.anchor=chooseAnchorProduct(s.anchor,el.value);saved=false;render();notify('製品を変更しました。許容耐力と根拠資料を再設定してください。');return;}let target=s;const keys=path.split('.'),last=keys.pop();keys.forEach(k=>target=target[k]);const v=el.type==='checkbox'?el.checked:el.type==='number'||el.dataset.number?Number(el.value):el.value;if(typeof v==='number'&&!Number.isFinite(v))return notify('数値を入力してください。');target[last]=v;if(path.startsWith('anchor.')){if(path!=='anchor.confirmed')s.anchor.confirmed=false;}saved=false;clearTimeout(renderTimer);renderTimer=setTimeout(()=>{const active=document.activeElement,focusPath=active?.dataset?.path;render();if(focusPath)document.querySelector(`[data-path="${focusPath}"]`)?.focus();},e.type==='input'?550:160);}
document.addEventListener('pointerdown',()=>clearTimeout(renderTimer),true);
document.addEventListener('input',handleField);document.addEventListener('change',handleField);
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.tab){tab=b.dataset.tab;render();return;}if(b.dataset.view){view=b.dataset.view;render();return;}if(b.dataset.preset){s.type=b.dataset.preset;regenerate();return;}if(b.dataset.mount){s.mount=b.dataset.mount;regenerate();return;}if(b.dataset.bent){const t=b.dataset.bent;s.bent.legs=t==='l'?[{length:50,turn:90},{length:80,turn:0}]:[{length:40,turn:90},{length:80,turn:t==='z'?-90:90},{length:40,turn:0}];saved=false;render();return;}if(b.dataset.delete){const keys=b.dataset.delete.split('.'),i=Number(keys.pop());let arr=s;keys.forEach(k=>arr=arr[k]);if(keys[0]==='nodes'){const id=s.nodes[i].id;if(s.members.some(m=>m.a===id||m.b===id)||s.loads.some(l=>l.node===id))return notify('接続する部材と荷重を先に削除してください。');}if(keys[0]==='bent'&&arr.length<=2)return notify('曲げ板には2辺以上が必要です。');arr.splice(i,1);saved=false;render();return;}
 switch(b.dataset.action){case 'regenerate':regenerate();break;case 'apply-all':s.members.forEach(m=>{m.section=s.defaultSection;m.material=s.material;});selected=s.defaultSection;saved=false;render();notify('全ての部材に適用しました。');break;case 'apply-section':s.defaultSection=selected;s.members.forEach(m=>m.section=selected);saved=false;render();notify('断面を全ての部材に適用しました。');break;case 'add-node':if(s.nodes.length>=40)return notify('節点は40個までです。');s.nodes.push({id:Math.max(0,...s.nodes.map(n=>n.id))+1,x:s.w,y:s.h,fix:'free',mount:s.mount});saved=false;render();break;case 'add-member':if(s.members.length>=80||s.nodes.length<2)return notify('部材上限または節点数を確認してください。');s.members.push({id:Math.max(0,...s.members.map(m=>m.id))+1,a:s.nodes[0].id,b:s.nodes[s.nodes.length-1].id,section:s.defaultSection,material:s.material,k:1});saved=false;render();break;case 'add-load':if(s.loads.length>=100)return notify('荷重は100件までです。');s.loads.push({node:s.nodes.at(-1)?.id,fx:0,fy:-1,mz:0});saved=false;render();break;case 'add-leg':if(s.bent.legs.length>=12)return notify('曲げ辺は12までです。');s.bent.legs.at(-1).turn=90;s.bent.legs.push({length:40,turn:0});saved=false;render();break;case 'save':save();break;case 'export-report':exportReport();break;case 'load':$('#file').click();break;case 'print':tab='report';modal=false;render();requestAnimationFrame(()=>window.print());break;case 'method':modal=true;render();break;case 'close':modal=false;render();break;}
});
$('#file').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;if(file.size>1000000){notify('1 MB以下の検討データを選んでください。');e.target.value='';return;}try{loadState(JSON.parse(await file.text()));notify('検討データを読み込みました。');}catch(err){notify('読み込めません：'+err.message);}e.target.value='';});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&modal){modal=false;render();}});
try{const stored=localStorage.getItem('support-studio-v1');if(stored)loadState(JSON.parse(stored));}catch{}render();

async function exportReport(){
 tab='report';modal=false;render();
 try{const css=await (await fetch('./style.css')).text();const html='<!doctype html><html lang="ja"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+esc(s.name)+' 構造一次検討書</title><style>'+css.replace(/@import[^;]+;/g,'')+'body{padding:24px}.main{max-width:1100px;padding:0}.preview-toolbar{display:none}.report-head{display:block}.no-print{margin-bottom:18px}@media print{body{padding:0}.no-print{display:none}}</style></head><body><main class="main"><div class="report-head"><h1>'+esc(s.name)+'</h1><p>配管架台 構造一次検討書 / '+new Date().toLocaleDateString('ja-JP')+'</p><p>平面線形弾性・参考計算。最終設計用の安全性判定ではありません。</p></div><button class="no-print primary" onclick="window.print()">印刷 / PDF保存</button>'+report()+'</main></body></html>';const blob=new Blob([html],{type:'text/html;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=(s.name||'pipe-support').replace(/[<>:"/\\|?*]/g,'_')+'_計算書.html';a.click();setTimeout(()=>URL.revokeObjectURL(url),3000);notify('計算書をHTMLで保存しました。ブラウザで開くと印刷・PDF保存できます。');}catch(e){notify('計算書を保存できませんでした。再度お試しください。');}
}

function anchorProductFields(){
 const a=s.anchor,p=anchorProducts[a.catalogId],missing=anchorMissing(a);
 return `<label class="field"><span>メーカー・製品を選択</span><select data-path="anchor.catalogId" aria-label="メーカー・製品を選択"><option value="custom" ${!p?'selected':''}>その他 / 手入力</option>${['HILTI','サンコーテクノ'].map(m=>`<optgroup label="${m}">${Object.entries(anchorProducts).filter(([,q])=>q.maker===m).map(([id,q])=>`<option value="${id}" ${a.catalogId===id?'selected':''}>${esc(q.name)}</option>`).join('')}</optgroup>`).join('')}</select></label>${p?`<div class="product-card"><div class="product-brand">${esc(p.maker)} <span>公式製品情報・2026-10-26確認</span></div><h3>${esc(p.name)}</h3><p>${p.type==='chemical'?'接着系注入式':'金属拡張・ウェッジ式'} / ${esc(p.material)}</p><a href="${p.url}" target="_blank" rel="noopener">公式製品・技術資料 ↗</a>${p.technical?` <a href="${p.technical}" target="_blank" rel="noopener">技術データ PDF ↗</a>`:''}<p>${esc(p.note)}</p>${p.diameters?`<p>掲載呼び径：${p.diameters.map(d=>'M'+d).join(' / ')}。径と全長の組合せは品番で確認。</p>`:''}</div>`:select('アンカーの種類','anchor.type',[['metal','金属拡張アンカー'],['chemical','接着系（ケミカル）アンカー']])+textField('メーカー・製品名','anchor.product','メーカー / 製品名')}${textField(p?.type==='chemical'?'ロッド形式・材質強度区分・品番':'製品品番・全長・材質区分','anchor.spec',p?.type==='chemical'?'採用ロッド、材質・強度区分、品番':'採用品番・全長を製品資料で確認')}${textField('採用設計基準・版・荷重区分','anchor.basis','基準名・版年、長期 / 短期など')}${textField('許容耐力の根拠資料・頁 / 計算書番号','anchor.source','メーカー資料名・版・頁、または計算書番号')}<div class="twocol">${select('コンクリートのひび割れ条件','anchor.crack',[['unknown','未指定'],['uncracked','ひび割れなしを想定'],['cracked','ひび割れありを想定']])}${select('採用耐力の荷重区分','anchor.duration',[['unknown','未指定'],['long','長期・持続'],['short','短期'],['seismic','地震時']])}</div>${textField('施工・使用条件メモ','anchor.installation','穿孔・清掃方法、温度、硬化、施工方向等')}<div class="note ${missing.length?'warning':''}" style="margin-bottom:16px">${missing.length?'未設定・要確認：'+missing.map(esc).join('、'):'製品情報と耐力の入力条件が揃っています。'}<br>製品選択だけでは耐力は設定されません。樹脂・ロッドやアンカー材質は架台材質と独立です。</div>`;
}
function anchorReportDetails(){const a=s.anchor,p=anchorProducts[a.catalogId];return `<p>アンカー製品詳細：${p?esc(p.maker+' / '+p.name)+' / '+esc(p.material):'手入力'}<br>品番・ロッド仕様：${esc(a.spec)||'未指定'}<br>採用設計基準：${esc(a.basis)||'未指定'}<br>許容耐力の根拠：${esc(a.source)||'未指定'}<br>ひび割れ条件：${({cracked:'ひび割れあり',uncracked:'ひび割れなし'})[a.crack]||'未指定'} / 荷重区分：${({long:'長期・持続',short:'短期',seismic:'地震時'})[a.duration]||'未指定'}<br>施工・使用条件：${esc(a.installation)||'未指定'}${p?`<br><a href="${p.url}" target="_blank" rel="noopener">メーカー公式製品資料</a>（製品情報確認日 2026-10-26）${p.technical?` / <a href="${p.technical}" target="_blank" rel="noopener">技術データ</a>`:''}`:''}<br>未設定・要確認：${anchorMissing(a).map(esc).join('、')||'入力項目なし（適用範囲は別途確認）'}</p>`;}
